import numpy as np
from scipy.optimize import least_squares

def refit_fixed_families(rows, seeds):
    seed_lookup={name:(f,b) for name,f,b,_ in seeds}
    out=[]
    for row in rows:
        seed_f,seed_b=seed_lookup[row['note']]
        n=np.array(row['partial_numbers']); actual=np.array(row['observed_peak_Hz'])
        def predict(params,indices):
            f,b=params
            return indices*f*np.sqrt((1+b*indices**2)/(1+b))
        def fit(keep):
            return least_squares(lambda p:1200*np.log2(actual[keep]/predict(p,n[keep])),[seed_f,seed_b],bounds=([seed_f*.98,0],[seed_f*1.02,.3]),x_scale=[seed_f,max(seed_b,1e-5)],max_nfev=2000)
        solution=fit(np.ones(len(n),bool)); residual=1200*np.log2(actual/predict(solution.x,n))
        loo=[]
        for k in range(len(n)):
            partfit=fit(np.arange(len(n))!=k)
            loo.append(float(1200*np.log2(actual[k]/predict(partfit.x,np.array([n[k]]))[0])))
        out.append({'note':row['note'],'f1_Hz':float(solution.x[0]),'B_effective':float(solution.x[1]),'residual_cents':residual.tolist(),'residual_Hz':(actual-predict(solution.x,n)).tolist(),'LOO_fixed_assignment_cents':loo})
    return out
